    phrase
        .split(|c: char| c.is_whitespace() || c == '-')
        .flat_map(word_letters)
        .collect()
}

fn word_letters(word: &str) -> impl Iterator<Item = String> {
    word.chars().filter_map(|c| {
        if c.is_alphabetic() {
            Some(c.to_uppercase().to_string())
        } else {
